// Differential checks of ReadBeforeWrite-faithful.js against Lean, generated by leanscript --check
import * as M from "./ReadBeforeWrite-faithful.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("test1(0n)", () => M.test1(0n), "14", false);
check("test1(1n)", () => M.test1(1n), "16", false);
check("test1(2n)", () => M.test1(2n), "18", false);
check("test1(5n)", () => M.test1(5n), "24", false);
check("test1(13n)", () => M.test1(13n), "40", false);
check("test5(0n)", () => M.test5(0n), "0", false);
check("test5(1n)", () => M.test5(1n), "4", false);
check("test5(2n)", () => M.test5(2n), "8", false);
check("test5(5n)", () => M.test5(5n), "20", false);
check("test5(13n)", () => M.test5(13n), "52", false);

console.log(`ReadBeforeWrite-faithful.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
